 ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use pretty_assertions :: assert_eq ; use crate :: { ToolCallArguments , ToolCallFull } ; use crate :: { ToolCallArguments , ToolCallFull } ; impl Todo { # [doc = " Creates a new todo with the given content"] pub fn new (content : impl Into < String >) -> Self { Self { id : String :: new () , content : content . into () , status : TodoStatus :: default () , } } # [doc = " Creates a test fixture todo"] # [cfg (test)] pub fn test () -> Self { Self { id : "test-id" . to_string () , content : "test content" . to_string () , status : TodoStatus :: default () , } } # [doc = " Validates the todo item"] # [doc = ""] # [doc = " # Errors"] # [doc = ""] # [doc = " Returns an error if:"] # [doc = " - Content is empty"] # [doc = " - Content exceeds maximum length (1000 characters)"] pub fn validate (& self) -> anyhow :: Result < () > { if self . content . trim () . is_empty () { anyhow :: bail ! ("Todo content cannot be empty") ; } if self . content . len () > 1000 { anyhow :: bail ! ("Todo content exceeds maximum length of 1000 characters") ; } Ok (()) } # [doc = " Checks if the todo is completed"] pub fn is_completed (& self) -> bool { self . status == TodoStatus :: Completed } # [doc = " Checks if the todo is incomplete (pending or in progress)"] pub fn is_incomplete (& self) -> bool { matches ! (self . status , TodoStatus :: Pending | TodoStatus :: InProgress) } }